CREATE OR REPLACE FUNCTION update_margin_util() RETURNS TRIGGER AS $$
DECLARE
    init_margin numeric;
    total_avail numeric;
    margin_util numeric;
BEGIN
    -- Get initial margin required from the risk profile JSONB
    init_margin := (NEW.margin_risk_profile->>'initial_margin_pct')::numeric;

    -- Get total available sum for the linked user
    SELECT COALESCE(SUM(ab."AVAIL_SUM"), 0) INTO total_avail
    FROM orders o
    JOIN users u ON o."UserRef" = u."USERSTAMP"
    JOIN accountbalances ab ON u."USERSTAMP" = ab."userTAG"
    WHERE o."ORD_STAMP" = NEW."ordStamp";

    -- Calculate margin utilization percentage
    IF total_avail > 0 THEN
        margin_util := ROUND(CAST(init_margin / total_avail * 100 AS numeric), 2);
    ELSE
        margin_util := 0;
    END IF;

    -- Update the JSONB with margin_util_pct
    NEW.margin_risk_profile := jsonb_set(NEW.margin_risk_profile, '{margin_util_pct}', to_jsonb(margin_util));

    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

